insert into agents (id, code, short_code, name, role, responsibilities, status, status_detail, current_project_id, current_ticket_id, last_run_at, outputs_produced, provider_policy, permission_level, required_capabilities, produces_artifact_types, consumes_artifact_types, can_execute_site_changes, created_at, updated_at, mission, exclusions, default_priority, instruction_pack_ids) values ('agent_orch', 'ORCH', 'ORCH', 'Conductor', 'Workflow coordination & human approval gates', '["Coordinates the complete workflow","Routes work to specialist agents","Enforces human approval gates","Never approves gates, performs AMBER/RED actions, or decides client scope"]'::jsonb, 'WAITING_APPROVAL', 'Human Review', NULL, NULL, NULL, 0, '{"preferred":"claude","fallbacks":["openai"],"reviewer":null}'::jsonb, 'AMBER', '["text","structured_output","long_context"]'::jsonb, '["project_brief","build_plan"]'::jsonb, '["research_report","site_blueprint","design_system","content_pack","build_report","qa_report","client_feedback"]'::jsonb, false, NULL, NULL, NULL, NULL, NULL, NULL) on conflict (id) do nothing;
