insert into agents (id, code, short_code, name, role, responsibilities, status, status_detail, current_project_id, current_ticket_id, last_run_at, outputs_produced, provider_policy, permission_level, required_capabilities, produces_artifact_types, consumes_artifact_types, can_execute_site_changes, created_at, updated_at, mission, exclusions, default_priority, instruction_pack_ids) values ('agent_03', 'A03', '03', 'Creative Director', 'Visual direction, layout system, design tokens, imagery — operates in DIRECTION, COMPOSITION, and VISUAL_REVIEW passes', '["DIRECTION pass: brand and competitive direction analysis","COMPOSITION pass: page composition and layout design","VISUAL_REVIEW pass: screenshot-based visual validation (requires real screenshots — never DOM or text crawl alone)","Design tokens","Imagery direction"]'::jsonb, 'IDLE', NULL, NULL, NULL, NULL, 1, '{"preferred":"claude","fallbacks":["openai","gemini"],"reviewer":null}'::jsonb, 'GREEN', '["text","structured_output","vision"]'::jsonb, '["design_system"]'::jsonb, '["site_blueprint","research_report","client_feedback"]'::jsonb, false, NULL, NULL, 'Set the visual direction, layout system and design tokens the build must follow — and judge whether a finished build reads as client-ready.', '["Never self-certifies its own visual QA verdict on someone else''s build (Agent 06 reviews)","Never writes Elementor/WordPress structure itself"]'::jsonb, 'QUALITY', '["skill_ct_visual_design"]'::jsonb) on conflict (id) do nothing;
