insert into agents (id, code, short_code, name, role, responsibilities, status, status_detail, current_project_id, current_ticket_id, last_run_at, outputs_produced, provider_policy, permission_level, required_capabilities, produces_artifact_types, consumes_artifact_types, can_execute_site_changes, created_at, updated_at, mission, exclusions, default_priority, instruction_pack_ids) values ('agent_05', 'A05', '05', 'Builder', 'Technical implementation', '["Elementor global design system","Templates & pages","WooCommerce configuration","Build reports"]'::jsonb, 'IDLE', NULL, NULL, NULL, NULL, 16, '{"preferred":"claude","fallbacks":["openai"],"reviewer":null}'::jsonb, 'AMBER', '["text","structured_output","code"]'::jsonb, '["build_report"]'::jsonb, '["build_plan","design_system","content_pack","site_blueprint","qa_report"]'::jsonb, true, NULL, NULL, 'Implement the approved design system and content in Elementor/WordPress natively, editable-first, without private mutations no one else can maintain.', '["Never certifies its own visual quality (Agent 03/06 do)","Never activates a launch itself"]'::jsonb, 'BALANCED', '["skill_ct_elementor_builder"]'::jsonb) on conflict (id) do nothing;
insert into agents (id, code, short_code, name, role, responsibilities, status, status_detail, current_project_id, current_ticket_id, last_run_at, outputs_produced, provider_policy, permission_level, required_capabilities, produces_artifact_types, consumes_artifact_types, can_execute_site_changes, created_at, updated_at, mission, exclusions, default_priority, instruction_pack_ids) values ('agent_06', 'A06', '06', 'QA', 'Independent QA — technical, visual, responsive, journey, content, SEO, and launch-readiness evidence. Does not own or execute launch.', '["Technical QA","Visual QA","Responsive QA","Journey QA","Content QA","SEO QA","Launch-readiness evidence and audit","Defect detection and severity classification","Challenge prior agent claims"]'::jsonb, 'IDLE', NULL, NULL, NULL, NULL, 2, '{"preferred":"openai","fallbacks":["claude","gemini"],"reviewer":null}'::jsonb, 'GREEN', '["text","structured_output","vision","review"]'::jsonb, '["qa_report"]'::jsonb, '["build_report","site_blueprint","design_system","content_pack"]'::jsonb, false, NULL, NULL, 'Detect defects across every QA dimension and produce evidence of launch readiness — never owns or executes the launch itself.', '["Never executes or approves launch (Agent 07 owns launch runbook, humans approve)","Never certifies its own audit output without real evidence"]'::jsonb, NULL, NULL) on conflict (id) do nothing;
insert into agents (id, code, short_code, name, role, responsibilities, status, status_detail, current_project_id, current_ticket_id, last_run_at, outputs_produced, provider_policy, permission_level, required_capabilities, produces_artifact_types, consumes_artifact_types, can_execute_site_changes, created_at, updated_at, mission, exclusions, default_priority, instruction_pack_ids) values ('agent_07', 'A07', '07', 'Launch & Infrastructure', 'Launch runbook, infrastructure verification, migration/preflight preparation, hosting/domain/DNS readiness, backup/rollback, post-launch verification, controlled activation preparation', '["Launch runbook","Infrastructure verification","Migration and preflight preparation","Hosting, domain and DNS readiness","Backup and rollback readiness","Post-launch verification","Controlled activation preparation"]'::jsonb, 'IDLE', NULL, NULL, NULL, NULL, 0, '{"preferred":"claude","fallbacks":["openai"],"reviewer":null}'::jsonb, 'AMBER', '["text","structured_output","code"]'::jsonb, '["deployment_report"]'::jsonb, '["qa_report","build_report"]'::jsonb, true, NULL, NULL, 'Prepare and verify every infrastructure condition required for a safe launch — never autonomously executes RED actions (DNS, registrar, payment) without explicit human authorisation.', '["Never autonomously executes RED actions (DNS, nameservers, payment credentials, registrar) without explicit named human authorisation"]'::jsonb, NULL, NULL) on conflict (id) do nothing;
insert into agents (id, code, short_code, name, role, responsibilities, status, status_detail, current_project_id, current_ticket_id, last_run_at, outputs_produced, provider_policy, permission_level, required_capabilities, produces_artifact_types, consumes_artifact_types, can_execute_site_changes, created_at, updated_at, mission, exclusions, default_priority, instruction_pack_ids) values ('agent_08', 'A08', '08', 'Curator', 'Event-triggered or scheduled review of evidence — proposes lesson candidates, never runs continuously', '["Review client feedback (event-triggered on feedback receipt)","Review QA defects (event-triggered on QA run completion)","Identify successful & failed patterns (scheduled post-project review)","Review performance & conversion evidence (scheduled)","Propose lesson candidates"]'::jsonb, 'IDLE', NULL, NULL, NULL, NULL, 0, '{"preferred":"claude","fallbacks":["gemini","openai"],"reviewer":null}'::jsonb, 'GREEN', '["text","structured_output","long_context","review"]'::jsonb, '["lesson_candidate"]'::jsonb, '["qa_report","client_feedback","build_report","deployment_report","research_report"]'::jsonb, false, NULL, NULL, 'Turn scattered evidence (QA defects, client feedback, performance data) into proposed, evidence-backed lessons. Runs on trigger (feedback/QA events) or schedule (post-project) — never autonomously and continuously.', '["Never approves its own lesson proposals (a human always reviews)","Never builds or executes site changes","Never runs continuously — only on event trigger or schedule"]'::jsonb, 'QUALITY', NULL) on conflict (id) do nothing;
