insert into skills (id, name, version, kind, status, scope, owner_agent_ids, reviewer_agent_ids, content, evidence, supersedes_id, approved_by, approved_by_id, approved_at, created_at, updated_at) values ('skill_ux_review_pack', 'UX & Conversion Review Checklist v1', 1, 'instruction_pack', 'APPROVED', 'agent-behaviour', '["agent_02"]'::jsonb, '["agent_06"]'::jsonb, 'Before proposing a sitemap or conversion journey: (1) every primary journey must resolve to one clear conversion goal — no page may leave the visitor without a next action; (2) IA depth stays at or under 3 clicks from home for any commercial page; (3) state the conversion logic in plain language a client can read, not just a diagram; (4) call out open questions explicitly rather than guessing at missing business context; (5) never propose a structure that requires a page type the build agent has not been given.', '["CTOS-003 seed — modelled on U-Proof site_blueprint reviews"]'::jsonb, NULL, 'Richard', NULL, NULL, NULL, NULL) on conflict (id) do nothing;
insert into skills (id, name, version, kind, status, scope, owner_agent_ids, reviewer_agent_ids, content, evidence, supersedes_id, approved_by, approved_by_id, approved_at, created_at, updated_at) values ('skill_ct_visual_design', 'CT Visual Design Skill v0.2', 2, 'design_review', 'CANDIDATE', 'design-review', '["agent_03"]'::jsonb, '["agent_06"]'::jsonb, '18-dimension structured visual review, never self-certified by the builder (A03 runs DIRECTION/COMPOSITION/VISUAL_REVIEW passes; A06 runs independent QA). Dimensions: BRAND_ALIGNMENT, VISUAL_HIERARCHY, LAYOUT_COMPOSITION, SPACING_RHYTHM, TYPOGRAPHY, COLOR_USE, IMAGERY, NAVIGATION, CTA_CLARITY, CONVERSION_CLARITY, TRUST, CONTENT_CLARITY, RESPONSIVENESS, MOBILE_USABILITY, PRODUCT_PRESENTATION, ORIGINALITY, POLISH, TECHNICAL_VISUAL_DEFECTS. Each dimension scored 1–5 and mapped to a verdict (A=4–5, B=3, C=1–2). Overall verdict uses priority order — any score ≤2 forces C, any score=3 forces B; no dimension averaging that hides a CRITICAL failure. Anti-generic rules enforced: no hero+3-cards commodity layouts; no generic icon sets as design features; no stock-photo hero images; no gradient-only buttons; no ''Why us?'' 3-icon grids; no footer-as-primary-navigation; no unverified counter badges (awards/years/etc). Screenshot evidence required at 1440px (desktop) and 375px (mobile) minimum before any review pass. All claims typed as OBSERVED/INFERRED/PROPOSED/VERIFIED — no evidence-free assertions. Evidence grounding: scores cite specific screenshot coordinates, section names, or element descriptions. Post-build gate sequence: BUILD → SCREENSHOT_CAPTURE → A03_VISUAL_REVIEW → A06_QA → HUMAN_APPROVAL → APPROVED.', '["U-Proof visual QA passes — desktop/tablet/mobile screenshot review","U-Proof product card legibility fixes","CTOS-005B 18-dimension rubric"]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL) on conflict (id) do nothing;
insert into skills (id, name, version, kind, status, scope, owner_agent_ids, reviewer_agent_ids, content, evidence, supersedes_id, approved_by, approved_by_id, approved_at, created_at, updated_at) values ('skill_ct_elementor_builder', 'CT Elementor Builder Skill v0.2', 2, 'build_practice', 'CANDIDATE', 'build-practice', '["agent_05"]'::jsonb, '["agent_06"]'::jsonb, 'Validated WordPress/Elementor implementation practice with build manifest governance (CTOS-005B): Build strategy per section: LIBRARY_ASSEMBLY (reuse approved section library pattern) or NATIVE_NOVEL_BUILD (new construction requiring noveltyJustification). LIBRARY_ASSEMBLY is the default — NATIVE_NOVEL_BUILD requires explicit written justification why no library pattern fits. Build manifest (elementor_build_manifest artifact) must record strategy, libraryEntryId, and humanEditProtection flag per section. humanEditProtection=true sections must not be overwritten by subsequent agent passes without human approval. Design tokens (color, typography, spacing) consumed from the active DesignTokenSet — no per-page overrides; required token kinds: color, typography, spacing. Build with native Elementor containers/widgets first — avoid giant custom HTML blobs; keep construction editable-first so a human can adjust it in the editor afterward; use the global Site Kit (colours, type, spacing) rather than per-page overrides; scope custom CSS narrowly and use custom JS only when a native option genuinely does not exist; any structured Elementor write (via the REST/DB layer) must be re-read and parsed immediately after writing, to confirm it saved as intended, not assumed from a 200 response; take a backup before any material mutation; wp_slash semantics differ between WP metadata APIs and raw DB writes — treat raw DB writes as a narrow fallback only, never the default path; verify Elementor page/template CSS actually propagated (not just that the save call succeeded); browser render validation is required — HTTP 200 is not visual QA; validate with real CDP viewport emulation at 1440/1254/1024/768/480/375; check shared header/footer consistency across templates; the builder never certifies its own final visual quality (Agent 03/06 do, via the CT Visual Design Skill); all work stays isolated from production until a human approves it, and every risky change has a stated rollback plan before it is made.', '["U-Proof Elementor build — global Site Kit usage","U-Proof structured write verification practice","CTOS-005B build manifest governance"]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL) on conflict (id) do nothing;
