insert into knowledge_items (id, scope, category, title, content, evidence, confidence, status, project_id, job_id, proposed_by_agent_id, reviewed_by, reviewed_at, created_at, updated_at) values ('kn_doctrine_pipeline', 'DOCTRINE', 'safety', 'Every build passes through the safety pipeline', 'BUILD → PREVIEW → HUMAN DESIGN APPROVAL → QA → FINAL REGRESSION AUDIT → CONTROLLED ACTIVATION TESTING → HUMAN LAUNCH APPROVAL → LIVE. No stage may be skipped by an agent.', '["state-machine SAFETY_PIPELINE"]'::jsonb, 1, 'APPROVED', NULL, NULL, NULL, 'Production Lead', NULL, NULL, NULL) on conflict (id) do nothing;
insert into knowledge_items (id, scope, category, title, content, evidence, confidence, status, project_id, job_id, proposed_by_agent_id, reviewed_by, reviewed_at, created_at, updated_at) values ('kn_doctrine_permissions', 'DOCTRINE', 'safety', 'GREEN / AMBER / RED permission tiers', 'GREEN actions run automatically. AMBER actions require explicit human approval before execution. RED actions (DNS, registrar, payment credentials, destructive infrastructure) are never executed by an agent without explicit, named authorization.', '["state-machine PERMISSION_MODEL"]'::jsonb, 1, 'APPROVED', NULL, NULL, NULL, 'Production Lead', NULL, NULL, NULL) on conflict (id) do nothing;
insert into knowledge_items (id, scope, category, title, content, evidence, confidence, status, project_id, job_id, proposed_by_agent_id, reviewed_by, reviewed_at, created_at, updated_at) values ('kn_doctrine_launch', 'DOCTRINE', 'safety', 'Launch never auto-approves', 'QA at zero is necessary, never sufficient, for launch. Launch requires human approval; approving with open launch holds is a deliberate, recorded human decision.', '["state-machine SAFETY_PIPELINE — LAUNCH gate"]'::jsonb, 1, 'APPROVED', NULL, NULL, NULL, 'Production Lead', NULL, NULL, NULL) on conflict (id) do nothing;
insert into knowledge_items (id, scope, category, title, content, evidence, confidence, status, project_id, job_id, proposed_by_agent_id, reviewed_by, reviewed_at, created_at, updated_at) values ('kn_doctrine_learning', 'DOCTRINE', 'process', 'Agents propose; humans approve knowledge', 'Agents may propose lesson candidates. No agent may promote its own output into AGENCY or DOCTRINE knowledge. Human approval is the only path from CANDIDATE to APPROVED.', '["CTOS-001 Part F"]'::jsonb, 1, 'APPROVED', NULL, NULL, NULL, 'Production Lead', NULL, NULL, NULL) on conflict (id) do nothing;
